/* Transcrição Cartório - Llama 3.2 Vision + Qwen2.5-VL
   base64 fica em variável local apenas — nunca no JSON do item entre nós */

const RUNPOD_URL = 'https://6y0yvpxgoqoth8-11434.proxy.runpod.net/api/chat';

// ── 1. Obter imagem ──────────────────────────────────────────────────────────
const item = $input.first();
let base64Image;

if (item.binary && Object.keys(item.binary).length > 0) {
  const key = Object.keys(item.binary)[0];
  const buf = await this.helpers.getBinaryDataBuffer(0, key);
  base64Image = buf.toString('base64');
} else if (item.json?.image) {
  base64Image = String(item.json.image).replace(/^data:image\/[a-z]+;base64,/, '');
} else {
  throw new Error('Nenhuma imagem. Use form-data (campo "image") ou JSON {"image":"base64..."}');
}

// ── Helper: parsear resposta NDJSON do Ollama ────────────────────────────────
function parseNDJSON(raw) {
  let text = '';
  if (typeof raw === 'string') {
    for (const line of raw.split('\n')) {
      if (!line.trim()) continue;
      try { text += JSON.parse(line)?.message?.content ?? ''; } catch(_) {}
    }
  } else if (raw?.message?.content) {
    text = raw.message.content;
  }
  return text;
}

async function ollamaChat(model, messages, temperature) {
  let raw;
  try {
    raw = await this.helpers.httpRequest({
      method: 'POST',
      url: RUNPOD_URL,
      body: { model, stream: true, keep_alive: -1, options: { temperature }, messages },
      json: true,
      timeout: 300000
    });
  } catch(httpErr) {
    const data = httpErr?.response?.data ?? '';
    if (typeof data === 'string' && data.includes('"done"')) {
      raw = data;
    } else {
      throw new Error(`Ollama ${model} falhou: ${httpErr.message}`);
    }
  }
  return parseNDJSON(raw);
}

// ── 2. Llama 3.2 Vision — rascunho ──────────────────────────────────────────
const llamaDraft = await ollamaChat.call(this,
  'llama3.2-vision:latest',
  [{
    role: 'user',
    content: 'Você é especialista em paleografia e registros civis brasileiros do século XX. ' +
             'Transcreva este documento de registro de nascimento de cartório. ' +
             'Extraia: nome do nascido, pai, mãe, data de nascimento, número do termo. ' +
             'Leia a letra manuscrita cursiva ao máximo. Use [ilegível] só se impossível.',
    images: [base64Image]
  }],
  0.1
);

console.log('Llama draft (200):', llamaDraft.substring(0, 200));

// ── 3. Qwen2.5-VL — extração final ──────────────────────────────────────────
const prompt =
  'Você é um especialista em paleografia e registros civis brasileiros do século XX.\n\n' +
  'Analise esta imagem de registro de nascimento de cartório.\n\n' +
  'Transcrição inicial de referência (use como guia, a imagem tem prioridade):\n---\n' +
  llamaDraft + '\n---\n\n' +
  'Extraia os campos abaixo com máxima precisão lendo a letra manuscrita.\n' +
  'Responda SOMENTE com JSON válido, sem texto antes ou depois:\n\n' +
  '{\n' +
  '  "nome_nascido": "nome completo da pessoa nascida",\n' +
  '  "nome_pai": "nome completo do pai ou null",\n' +
  '  "nome_mae": "nome completo da mae ou null",\n' +
  '  "data_nascimento": "data como escrita no documento",\n' +
  '  "ano": "somente o ano ex: 1931",\n' +
  '  "numero_termo": "numero do Termo ou Assento",\n' +
  '  "municipio": "municipio ou null",\n' +
  '  "estado": "UF ex: PE ou null",\n' +
  '  "confianca": "alta|media|baixa",\n' +
  '  "observacoes": "campos duvidosos ou ilegíveis"\n' +
  '}';

const qwenRaw = await ollamaChat.call(this,
  'qwen2.5vl:7b',
  [{ role: 'user', content: prompt, images: [base64Image] }],
  0.05
);

// base64Image descartada aqui — variável local, GC pode limpar
base64Image = null;

console.log('Qwen raw (300):', qwenRaw.substring(0, 300));

// ── 4. Parsear JSON da resposta ──────────────────────────────────────────────
const cleaned = qwenRaw.replace(/```json\n?|\n?```/g, '').trim();
let result = {};
try {
  const match = cleaned.match(/\{[\s\S]*\}/);
  result = match ? JSON.parse(match[0]) : { erro: 'JSON nao encontrado', raw: qwenRaw };
} catch(e) {
  result = { erro: e.message, raw: qwenRaw };
}

return [{
  json: {
    ...result,
    _meta: {
      model_rascunho: 'llama3.2-vision:latest',
      model_final: 'qwen2.5vl:7b',
      rascunho: llamaDraft,
      processado_em: new Date().toISOString()
    }
  }
}];
